# Input data
n_weeks = 4      # Number of weeks
n_groups = 3     # Number of groups per week
group_size = 3   # Size of each group

n_golfers = n_groups * group_size

# Model definition
model = cp_model.CpModel()

# Decision variables:
# assign[w][g][s]: golfer assigned to slot s in group g in week w
assign = []
for w in range(n_weeks):
    week = []
    for g in range(n_groups):
        group = [
            model.NewIntVar(0, n_golfers - 1, f'assign_w{w}_g{g}_s{s}')
            for s in range(group_size)
        ]
        week.append(group)
    assign.append(week)

# 1. Each golfer plays exactly once per week
for w in range(n_weeks):
    all_golfers = [assign[w][g][s] for g in range(n_groups) for s in range(group_size)]
    model.AddAllDifferent(all_golfers)

# 2. No golfer plays in the same group as any other golfer more than once
# For each pair of golfers, count the number of times they are together in a group
# For each week, for each group, for each pair in the group, record (w, g, s1, s2)
pair_played_together = {}
for i in range(n_golfers):
    for j in range(i + 1, n_golfers):
        pair_played_together[(i, j)] = []

for w in range(n_weeks):
    for g in range(n_groups):
        for s1 in range(group_size):
            for s2 in range(s1 + 1, group_size):
                # For each pair of slots in the group, if they are (i, j), then they play together
                i_var = assign[w][g][s1]
                j_var = assign[w][g][s2]
                for (a, b) in pair_played_together:
                    # Add a boolean variable that is true if (i_var, j_var) == (a, b) or (b, a)
                    together = model.NewBoolVar(f'together_w{w}_g{g}_s{s1}_{s2}_p{a}_{b}')
                    model.AddBoolOr([
                        model.NewAnd([i_var == a, j_var == b]),
                        model.NewAnd([i_var == b, j_var == a])
                    ]).OnlyEnforceIf(together)
                    model.AddBoolAnd([
                        model.NewOr([i_var != a, j_var != b]),
                        model.NewOr([i_var != b, j_var != a])
                    ]).OnlyEnforceIf(together.Not())
                    pair_played_together[(a, b)].append(together)

# Each pair can play together at most once
for pair, bools in pair_played_together.items():
    model.Add(sum(bools) <= 1)

# 3. No duplicate golfers in a group in a week (already enforced by AllDifferent per week)

# 4. Optional: symmetry breaking
# - Order golfers in each group by index (to reduce symmetry)
for w in range(n_weeks):
    for g in range(n_groups):
        for s in range(group_size - 1):
            model.Add(assign[w][g][s] < assign[w][g][s + 1])
# - Order first group in first week
for s in range(group_size):
    model.Add(assign[0][0][s] == s)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # Build the assignment output
    assign_out = []
    for w in range(n_weeks):
        week = []
        for g in range(n_groups):
            group = [solver.Value(assign[w][g][s]) for s in range(group_size)]
            week.append(group)
