import json

# Input data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

model = cp_model.CpModel()

# Decision variables

# is_host[b]: 1 if boat b is a host, 0 otherwise
is_host = [model.NewBoolVar(f'is_host_{b}') for b in range(n_boats)]

# visits[g][t][h]: 1 if guest boat g visits host h at period t
# Only for g != h
visits = []
for g in range(n_boats):
    visits_g = []
    for t in range(n_periods):
        visits_g_t = []
        for h in range(n_boats):
            if g == h:
                visits_g_t.append(None)  # Not used
            else:
                visits_g_t.append(model.NewBoolVar(f'visits_g{g}_t{t}_h{h}'))
        visits_g.append(visits_g_t)
    visits.append(visits_g)

# Constraints

# 1. A host's own crew stays on board, guests visit hosts, guests never visit themselves
# 2. Each guest boat visits exactly one host in each period (cannot visit itself, cannot stay idle)
for g in range(n_boats):
    # If g is a host, its crew stays on board, so it does not visit anyone
    for t in range(n_periods):
        # For guest boats only (not hosts)
        # If g is not a host, it must visit exactly one host in each period
        model.Add(sum(visits[g][t][h] for h in range(n_boats) if h != g and visits[g][t][h] is not None) == 1).OnlyEnforceIf(is_host[g].Not())
        # If g is a host, it does not visit anyone
        for h in range(n_boats):
            if h != g and visits[g][t][h] is not None:
                model.Add(visits[g][t][h] == 0).OnlyEnforceIf(is_host[g])

# 3. Guests can only visit hosts
for g in range(n_boats):
    for t in range(n_periods):
        for h in range(n_boats):
            if h != g and visits[g][t][h] is not None:
                # Only possible to visit h if h is a host
                model.Add(visits[g][t][h] <= is_host[h])

# 4. No guest visits the same host more than once
for g in range(n_boats):
    for h in range(n_boats):
        if g != h:
            model.Add(sum(visits[g][t][h] for t in range(n_periods)) <= 1)

# 5. No two guest crews meet more than once
# For each pair of guest boats (g1, g2), count the number of periods where they visit the same host
for g1 in range(n_boats):
    for g2 in range(g1 + 1, n_boats):
        if g1 != g2:
            for t in range(n_periods):
                for h in range(n_boats):
                    if h != g1 and h != g2 and visits[g1][t][h] is not None and visits[g2][t][h] is not None:
                        # If both g1 and g2 visit h at t, then they meet
                        # We'll count the number of meetings over all periods and hosts
                        # For each pair, sum over all periods and hosts, must be <= 1
                        pass
            # Build a list of BoolVars for all possible meetings
            meet_vars = []
            for t in range(n_periods):
                for h in range(n_boats):
                    if h != g1 and h != g2 and visits[g1][t][h] is not None and visits[g2][t][h] is not None:
                        meet = model.NewBoolVar(f'meet_g{g1}_g{g2}_t{t}_h{h}')
                        model.AddBoolAnd([visits[g1][t][h], visits[g2][t][h]]).OnlyEnforceIf(meet)
                        model.AddBoolOr([visits[g1][t][h].Not(), visits[g2][t][h].Not()]).OnlyEnforceIf(meet.Not())
                        meet_vars.append(meet)
            model.Add(sum(meet_vars) <= 1)

# 6. Capacity constraints: For each host h, in each period t, the total number of people on board <= capacity[h]
for h in range(n_boats):
    for t in range(n_periods):
        # Host's own crew is always on board if h is a host
        # Sum up all guest crews visiting h at t
        guest_sum = []
        for g in range(n_boats):
            if g != h and visits[g][t][h] is not None:
                guest_sum.append(visits[g][t][h] * crew_size[g])
        # If h is a host, then its own crew is on board, plus guests
        # If h is not a host, no one is on board (no guests can visit, enforced above)
        total_onboard = sum(guest_sum) + crew_size[h]
        # Only enforce if h is a host
        model.Add(total_onboard <= capacity[h]).OnlyEnforceIf(is_host[h])

# 7. At least one host
model.Add(sum(is_host) >= 1)

# Objective: minimize the number of hosts
model.Minimize(sum(is_host))

# Solve the model
solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 60.0
status = solver.Solve(model)

# Prepare output
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # visits[g][t][h]: 1 if guest g visits host h at period t, 0 otherwise (None for g==h)
    visits_out = []
    for g in range(n_boats):
        visits_g = []
        for t in range(n_periods):
            visits_g_t = []
            for h in range(n_boats):
                if g == h or visits[g][t][h] is None:
                    visits_g_t.append(0)
                else:
                    visits_g_t.append(solver.Value(visits[g][t][h]))
            visits_g.append(visits_g_t)
        visits_out.append(visits_g)
    is_host_out = [solver.Value(is_host[b]) for b in range(n_boats)]
    solution = {
        'visits': visits_out,
        'is_host': is_host_out
    }
    print(json.dumps(solution, indent=4))
