            for t in range(n_periods):
                for h in range(n_boats):
                    if h != g1 and h != g2 and visits[g1][t][h] is not None and visits[g2][t][h] is not None:
                        # If both g1 and g2 visit h at t, then they meet
                        # We'll count the number of meetings over all periods and hosts
                        # For each pair, sum over all periods and hosts, must be <= 1
                        pass
            # Build a list of BoolVars for all possible meetings
            meet_vars = []
            for t in range(n_periods):
                for h in range(n_boats):
                    if h != g1 and h != g2 and visits[g1][t][h] is not None and visits[g2][t][h] is not None:
                        meet = model.NewBoolVar(f'meet_g{g1}_g{g2}_t{t}_h{h}')
                        model.AddBoolAnd([visits[g1][t][h], visits[g2][t][h]]).OnlyEnforceIf(meet)
                        model.AddBoolOr([visits[g1][t][h].Not(), visits[g2][t][h].Not()]).OnlyEnforceIf(meet.Not())
                        meet_vars.append(meet)
            model.Add(sum(meet_vars) <= 1)

# 6. Capacity constraints: For each host h, in each period t, the total number of people on board <= capacity[h]
for h in range(n_boats):
    for t in range(n_periods):
        # Host's own crew is always on board if h is a host
        # Sum up all guest crews visiting h at t
        guest_sum = []
        for g in range(n_boats):
            if g != h and visits[g][t][h] is not None:
                guest_sum.append(visits[g][t][h] * crew_size[g])
        # If h is a host, then its own crew is on board, plus guests
        # If h is not a host, no one is on board (no guests can visit, enforced above)
        total_onboard = sum(guest_sum) + crew_size[h]
        # Only enforce if h is a host
        model.Add(total_onboard <= capacity[h]).OnlyEnforceIf(is_host[h])

# 7. At least one host
model.Add(sum(is_host) >= 1)

# Objective: minimize the number of hosts
model.Minimize(sum(is_host))

# Solve the model
solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 60.0
status = solver.Solve(model)

# Prepare output
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
