            for h in range(n_boats):
                if g == h or visits[g][t][h] is None:
                    visits_g_t.append(0)
                else:
                    visits_g_t.append(solver.Value(visits[g][t][h]))
            visits_g.append(visits_g_t)
        visits_out.append(visits_g)
    is_host_out = [solver.Value(is_host[b]) for b in range(n_boats)]
    solution = {
